Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

Notation zlen l := (Z.of_nat (length l)).

(* [comment removed for export] *)
Definition w4rel (L pt b st : Z) : Prop :=
  (st = 0 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b <= 64 /\ (8 <= pt -> b <= 8))) \/
  (st = 3 /\ (0 <= pt /\ (pt = 0 \/ pt + 8 <= L) /\ 0 <= b < 2^31)).

(* [comment removed for export] *)
Ltac kxg_vals :=
  repeat match goal with
  | |- context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H := fresh "HR" in kx_range (EVar j) H; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in |- *; clearbody w ]
  end;
  repeat match goal with
  | |- context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H := fresh "HR" in kx_range e H; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in |- *; clearbody w ]
  end.
Ltac kxg_hyp H :=
  repeat match type of H with
  | context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H' := fresh "HR" in kx_range (EVar j) H'; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w ]
  end;
  repeat match type of H with
  | context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H' := fresh "HR" in kx_range e H'; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w ]
  end.
Ltac kxg_clear :=
  lazymatch goal with
  | HK : know_ok _ ?E _ _ |- _ =>
      let b := eval unfold E in E in
      repeat match goal with H : context [E] |- _ => clear H end;
      try clear E;
      lazymatch b with kx_env _ ?xs => try clear xs | _ => idtac end
  end.

Definition w4s1_r12_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x22 x23 x24 x28 x29 x30 x31 : word)
         (P SS n SBL SBH l1 l2 pt1 pt2 PTR1 PTR2 P1 P2 C1 C2 : Z),
    PTR1 = SS + 6 + pt1 -> PTR2 = SS + 6 + l1 + pt2 ->
    w4s_src_ctx RNG mm SS n SBL SBH -> n < 2^26 ->
    rw_cells asegs mm (P + 176) [C8 (Z_to_bv 64 (SS + 14)); C8 (Z_to_bv 64 (SS + 6 + l1 + 8))] ->
    rw_cells asegs mm (P + 224) [C8 (Z_to_bv 64 C2)] -> rw_cells asegs mm (P + 232) [C8 (Z_to_bv 64 C1)] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> KXGoM.apart SS n P 496 ->
    1 <= l1 -> 1 <= l2 -> 6 + l1 + l2 <= n ->
    0 <= pt1 -> (pt1 = 0 \/ pt1 + 8 <= l1) -> 0 <= pt2 -> (pt2 = 0 \/ pt2 + 8 <= l2) ->
    0 <= P1 <= 112 -> 0 <= P2 <= 100 -> (8 <= pt1 -> P1 <= 56) -> (8 <= pt2 -> P2 <= 44) ->
    0 <= bv_unsigned x7 <= 12 -> 0 <= C1 < 2^64 -> 0 <= C2 < 2^64 ->
    (forall (mm' : amem) (PT1 PT2 ST1 ST2 : Z) (b1w b2w c1' c2' j6 j7 j12 j14 j17 j29 j31 : word),
       munch [(P + 224, P + 240)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 224) [C8 c2'] -> rw_cells asegs mm' (P + 232) [C8 c1'] ->
       w4rel l1 (PT1 - (SS + 6)) (bv_unsigned b1w) ST1 -> w4rel l2 (PT2 - (SS + 6 + l1)) (bv_unsigned b2w) ST2 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 j6 j7 x8 x9 x10 (Z_to_bv 64 ST2) j12 (Z_to_bv 64 ST1) j14 x15 x16
                                 j17 x18 x19 x20 b2w x22 x23 x24 (Z_to_bv 64 PT2) (Z_to_bv 64 PT1) b1w x28 j29 x30 j31)
                            F (Z_to_bv 64 0x913d8) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20
                             (Z_to_bv 64 P2) x22 x23 x24 (Z_to_bv 64 PTR2) (Z_to_bv 64 PTR1) (Z_to_bv 64 P1) x28 x29 x30 x31)
                        F (Z_to_bv 64 0x91298) fc None mm (seg_rom asegs)).

Ltac w4s12_post K C224 C232 P mm :=
  kx_post_regs_keep;
  let MU := fresh "MU" in let WM := fresh "WM" in
  pose proof (munch_refl [(P + 224, P + 240)] mm) as MU;
  pose proof (wmono_refl asegs mm) as WM;
  kx_munch_wins MU [(P + 224, 8); (P + 232, 8)];
  first [kx_cellw C224 | kx_frame C224];
  try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => cbn [cells_size csize]; lia end);
  first [kx_cellw C232 | kx_frame C232];
  try (lazymatch goal with |- evtF _ _ _ _ => fail | _ => cbn [cells_size csize]; lia end);
  kx_post_mem_free;
  lazymatch goal with |- context [mem_denot ?E mm ?l] => let EM := fresh "EM" in remember (mem_denot E mm l) as mm' eqn:EM; clear EM end;
  kxg_hyp C224; kxg_hyp C232;
  kxg_vals;
  kxg_clear;
  eapply K; [ exact MU | exact WM | eassumption | exact C224 | exact C232 | .. ].

Ltac w4s12_rel := unfold w4rel; rewrite ?Z_to_bv_unsigned, ?bv_wrap_small by (unfold bv_modulus; cbn; lia);
  first [ left; split; [reflexivity| lia] | right; split; [reflexivity| lia] ].

